/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import { loadFont } from "@remotion/google-fonts/Inter";
import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useId,
} from "react";
import {
  AbsoluteFill,
  Interactive,
  type InteractivitySchema,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

/**
 * Every number here was measured off a 1920x1080 reference, one sample per frame.
 * Sizes and offsets are px on that stage.
 */

const FONT_SIZE = 130;
/** Where the type sits at rest. */
const BASELINE = 574.5;

/** Frames each card holds: the first, every word between, the last. */
const HOLDS = { first: 9, word: 7, last: 15 } as const;

/** The first word lands low and rises into place: px below rest, per frame. */
const RISE = [70, 43, 22.8, 13, 7.2, 3.7, 1.55, 0.45, 0] as const;

/** The last card, frame by frame: how far the word has sunk. The dot stays put. */
const DROP = [
  0, 0, 0, 0, 0.38, 1.25, 2.54, 4.4, 6.91, 10.27, 14.57, 20.23, 27.57, 37.53,
  51.55,
] as const;

/** Between the x-height and the dot, in em above the baseline, where no face is told. */
const DOT_LINE = 0.585;

const { fontFamily: inter } = loadFont("normal", { weights: ["700"] });

const STAGE_W = 1920;
const STAGE_H = 1080;
/** Words may fill this much of the stage width before they scale down to fit. */
const MAX_WIDTH = STAGE_W * 0.9;
const DOTTED = /[ij]/;

/**
 * Drop Line: words cut in place, the first rising into position, and on the last
 * card the word sinks out from under its own dot. The dot holds its position, so
 * the sentence ends on one mark left hanging. A last word with no "i" or "j" just
 * drops whole.
 */
export interface DropLineProps {
  /** One word per card; the last one drops. */
  words?: string[];
  fontFamily?: string;
  fontWeight?: number;
  /** Type size on a 1920x1080 stage. */
  fontSize?: number;
  /** Size per word on that stage, for faces that set a card differently. */
  wordSize?: number[];
  /** Horizontal nudge per word, in stage px, for optical centring. */
  wordNudge?: number[];
  /** Tracking per word in em. */
  wordTracking?: number[];
  /** Per-letter offsets per word, in em. */
  wordKerning?: number[][];
  /** The card. Defaults to the theme foreground. */
  ink?: string;
  /** The type. Defaults to the theme background. */
  paper?: string;
  speed?: number;
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

/** Sample a measured table at a fractional frame; holds both ends. */
const sample = (table: readonly number[], at: number) => {
  const x = Math.max(0, Math.min(at, table.length - 1));
  const i = Math.floor(x);
  const a = table[i] ?? 0;
  return a + ((table[i + 1] ?? a) - a) * (x - i);
};

/** Frame each word cuts in, the frame the last card ends, and when its drop table starts. */
const timeline = (count: number) => {
  const starts = Array.from({ length: count }, (_, i) =>
    i === 0 ? 0 : HOLDS.first + (i - 1) * HOLDS.word,
  );
  const end = HOLDS.first + Math.max(0, count - 2) * HOLDS.word + HOLDS.last;
  return { starts, end, drop: end - DROP.length };
};

/** Which card is up at frame `f`. */
const cardAt = (starts: readonly number[], f: number) =>
  starts.reduce((at, s, i) => (f >= s ? i : at), 0);

let measureCtx: CanvasRenderingContext2D | null | undefined;

const fontMeasure = (font: string) => {
  if (typeof document === "undefined") return null;
  if (measureCtx === undefined) {
    measureCtx = document.createElement("canvas").getContext("2d");
  }
  if (measureCtx) measureCtx.font = font;
  return measureCtx ?? null;
};

/**
 * A line that can sit a fraction of a pixel. Chrome rounds a baseline to a whole
 * device pixel, which turns a slow drop into a staircase, so the type is painted
 * on the two rows around `y` and added by the fraction between them.
 */
const Line: React.FC<{
  y: number;
  base: number;
  px: number;
  children: ReactNode;
}> = ({ y, base, px, children }) => {
  const row = Math.floor(y * px);
  const f = y * px - row;
  return (
    <g style={{ isolation: "isolate" }}>
      {[
        { r: row, w: 1 - f },
        { r: row + 1, w: f },
      ].map(({ r, w }) => (
        <g
          key={r}
          transform={`translate(0 ${(r + 1e-3) / px - base})`}
          style={{ opacity: w, mixBlendMode: "plus-lighter" }}
        >
          {children}
        </g>
      ))}
    </g>
  );
};

const DropLineScene: React.FC<DropLineProps> = ({
  words = ["then", "ships", "the", "film"],
  fontFamily = inter,
  fontWeight = 700,
  fontSize = 130,
  wordSize,
  wordNudge,
  wordTracking,
  wordKerning,
  ink,
  paper,
  speed = 1,
  theme,
  mode,
}) => {
  const t = useKitTheme(theme, mode);
  const uid = useId().replace(/:/g, "");
  const f = useCurrentFrame() * speed;
  const { width, height } = useVideoConfig();
  const px = Math.max(width / STAGE_W, height / STAGE_H);
  const card = ink ?? t.foreground;
  const type = paper ?? t.background;

  const line = timeline(words.length);
  const index = cardAt(line.starts, f);
  const word = words[index] ?? "";
  const isLast = index === words.length - 1;
  const chars = Array.from(word);
  const tracking = wordTracking?.[index] ?? -0.015;

  const wanted = wordSize?.[index] ?? fontSize;
  const ctx = fontMeasure(`${fontWeight} ${wanted}px ${fontFamily}`);
  const measured =
    (ctx ? ctx.measureText(word).width : chars.length * wanted * 0.6) +
    (chars.length - 1) * tracking * wanted;
  const fit = Math.min(1, MAX_WIDTH / Math.max(1, measured));
  const size = wanted * fit;

  // Keep the type centred on the stage as `fontSize` moves away from the measured one.
  const rest = STAGE_H / 2 + (BASELINE - STAGE_H / 2) * (fontSize / FONT_SIZE);
  const fall = isLast ? sample(DROP, f - line.drop) : 0;
  const y = rest + (index === 0 ? sample(RISE, f) : 0);

  // The cut between a dot and its stem: just above the x-height, on any face.
  const dots = isLast && DOTTED.test(word);
  const xHeight = ctx?.measureText("x").actualBoundingBoxAscent;
  const dotTop = ctx?.measureText("i").actualBoundingBoxAscent;
  const dotLine =
    xHeight && dotTop
      ? rest - (xHeight + (dotTop - xHeight) * 0.15) * fit
      : rest - DOT_LINE * size;

  const letters = (show: (ch: string) => boolean) => (
    <text
      x={STAGE_W / 2 + (wordNudge?.[index] ?? 0)}
      y={rest}
      textAnchor="middle"
      fill={type}
      style={{
        fontFamily,
        fontWeight,
        fontSize: size,
        letterSpacing: `${tracking}em`,
        textRendering: "geometricPrecision",
      }}
    >
      {chars.map((ch, i) => (
        <tspan
          // biome-ignore lint/suspicious/noArrayIndexKey: letters of a fixed string
          key={i}
          dx={`${wordKerning?.[index]?.[i] ?? 0}em`}
          fillOpacity={show(ch) ? 1 : 0}
        >
          {ch}
        </tspan>
      ))}
    </text>
  );

  return (
    <AbsoluteFill
      showInTimeline={false}
      style={{ background: card, overflow: "hidden" }}
    >
      <svg
        viewBox={`0 0 ${STAGE_W} ${STAGE_H}`}
        width="100%"
        height="100%"
        preserveAspectRatio="xMidYMid slice"
        style={{ position: "absolute", inset: 0 }}
      >
        <title>{words.join(" ")}</title>
        <defs>
          <clipPath id={`${uid}a`}>
            <rect width={STAGE_W} height={dotLine} />
          </clipPath>
          <clipPath id={`${uid}b`}>
            <rect y={dotLine} width={STAGE_W} height={STAGE_H * 2} />
          </clipPath>
        </defs>
        <Line y={y + fall} base={rest} px={px}>
          {dots ? (
            <>
              {letters((ch) => !DOTTED.test(ch))}
              <g clipPath={`url(#${uid}b)`}>
                {letters((ch) => DOTTED.test(ch))}
              </g>
            </>
          ) : (
            letters(() => true)
          )}
        </Line>
        {dots && (
          <Line y={y} base={rest} px={px}>
            <g clipPath={`url(#${uid}a)`}>{letters((ch) => DOTTED.test(ch))}</g>
          </Line>
        )}
      </svg>
    </AbsoluteFill>
  );
};

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type DropLineElementProps = Omit<
  ComponentProps<typeof DropLineScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const DropLineDefaults = {
  fontSize: 130,
  speed: 1,
} satisfies Partial<DropLineElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const DropLineSchema = {
  fontSize: {
    type: "number",
    default: 130,
    min: 48,
    max: 240,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
    keyframable: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function DropLineFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const DropLineInner = forwardRef<HTMLDivElement, DropLineElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...DropLineDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <DropLineFade>
            <DropLineScene key={key} {...rest} />
          </DropLineFade>
        </div>
      </Sequence>
    );
  },
);

export const DropLine = Interactive.withSchema({
  Component: DropLineInner,
  componentName: "<DropLine>",
  schema: DropLineSchema,
  wrapInSequence: true,
});
